-- [v43.2 i18n] French waypoint comments.
--
-- The route data ships lComments for enUS and deDE only - ~296 waypoints
-- (207 distinct strings), and they are the safety-critical ones: "caution,
-- from here this route runs along the edge of a gorge", "wait here for the
-- zeppelin", "this NPC moves". This file is what SkuNav:PlayWpComments speaks
-- on a French client instead of falling back to English.
--
-- KEYED ON THE GERMAN STRING, deliberately, for two reasons:
--   * German is the original. The English is a relay translation that lost
--     detail (the gorge warning drops "you walk on the edge" and the direction
--     of travel) and carries grammar errors ("this route is a the edge of").
--   * German is always filled. Several waypoints have an enUS entry that is
--     empty or a single space - including the "elevators can be lethal"
--     warning on 8 waypoints, which English-speaking users have never heard.
--
-- Proper nouns are NOT translated by hand. They come from SkuDB's own
-- SkuDB.NpcData.Names.frFR (Blizzard strings via Questie), Questie's zone
-- tables, a /skudebug dumpmapnames capture on a real frFR client, and
-- Wowhead's tooltip API for the WotLK NPCs the first three do not cover.
--
-- Quoted WAYPOINT names are kept exactly as a French client announces them,
-- which is usually ENGLISH: the hand-authored route names are not translated
-- (their third §-field equals the first). Translating those quotes would send
-- the player looking for a point that is never spoken that way. Checked
-- individually against the route data; the one genuinely translated case is
-- "sauvetage;point;cave;Lushwater Oasis;Les Tarides".
--
-- Register is vouvoiement, matching locales/frFR.lua.

SkuWaypointComments = SkuWaypointComments or {}
SkuWaypointComments["frFR"] = {
	["Fliegen starten / beenden"] = "Début / fin du vol",
	["Hier auf den Fahrstuhl warten!"] = "Attendez ici l'ascenseur !",
	["Achtung: Questgeber bewegt sich!"] = "Attention : le donneur de quête se déplace !",
	["Hier auf das Schiff warten !"] = "Attendez ici le bateau !",
	["Hier auf den Zeppelin warten!"] = "Attendez ici le zeppelin !",
	["Warnung: Lifte können tödlich sein. Sicherer sind Gneis Wege!"] = "Avertissement : les ascenseurs peuvent être mortels. Les chemins de Gneis sont plus sûrs !",
	["Achtung der Questgeber bewegt sich. Allenfalls beim anderen Wegpunkt suchen!"] = "Attention, le donneur de quête se déplace. Le cas échéant, cherchez-le à l'autre point de passage !",
	["hier kommt ein schmaler steg"] = "Ici commence une passerelle étroite",
	["Von hier eine Sekunde geradeaus laufen, um durch das Portal zu gehen."] = "À partir d'ici, avancez tout droit pendant une seconde pour franchir le portail.",
	["Achtung: Anfang oder Ende der Brücke!"] = "Attention : début ou fin du pont !",
	["Brückenkopf mittlere Brücke"] = "Tête de pont, pont du milieu",
	["Fahrstuhl!"] = "Ascenseur !",
	["Brückenkopf nördliche Brücke"] = "Tête de pont, pont nord",
	["STOP! Von hier musst du sehr vorsichtig den Berg runter rutschen, um nach unten zu kommen. Navigiere 100% präzise! Wenn du fällst, heile oder verbinde dich, bevor du weiter läufst!"] = "STOP ! À partir d'ici, vous devez descendre la montagne en glissant très prudemment. Naviguez avec une précision de 100 % ! Si vous tombez, soignez-vous ou bandez vos blessures avant de repartir !",
	["Brückenkopf südliche Brücke"] = "Tête de pont, pont sud",
	["Umleitung an der Horde vorbei, durch die Wildniss. Vorsicht vor Wildtieren. Ende/Anfang"] = "Détour évitant la Horde, à travers la nature sauvage. Méfiez-vous des animaux sauvages. Fin/Début",
	["Hier einmal vorwärts Springen!"] = "Sautez une fois vers l'avant ici !",
	["Überprüfe nochmals ob du wirklich alle Quests im Eisklamm-Tal erledigt hast, bevor du in die nächste Stadt aufbrichst."] = "Vérifiez encore une fois que vous avez bien terminé toutes les quêtes de la Vallée des Frigères avant de partir pour la ville suivante.",
	["Der Erzmagier läuft zwischen den beiden Routenpunkten."] = "L'archimage fait la navette entre les deux points de la route.",
	["Achtung: nächster Wegpunkt ist der Zeppelin Anleger!"] = "Attention : le prochain point de passage est l'embarcadère du zeppelin !",
	["Töte die beiden Kerkermeister und öffne mit den Schlüsseln die Schlösser zu den Füssen der Gefangenen mit rechtklick. "] = "Tuez les deux geôliers et ouvrez avec les clés les serrures aux pieds des prisonniers par un clic droit.",
	["Auf Schiff Warten"] = "Attendez le bateau",
	["Achtung: NPC bewegt sich!"] = "Attention : le PNJ se déplace !",
	["Questgeber bewegt sich!"] = "Le donneur de quête se déplace !",
	["Vorsicht vor dem Kurier der Verlassenen und seiner Leibwache"] = "Méfiez-vous de la Messagère des Réprouvés et de son garde du corps",
	["Hier auf den Lift warten !"] = "Attendez ici l'ascenseur !",
	["Springe so lange, bis sich die Entferung zum Ziel verändert. Laufe dann sofort vorwärts, bis du nicht mehr feststeckst."] = "Sautez sans vous arrêter jusqu'à ce que la distance jusqu'à la cible change. Courez alors immédiatement vers l'avant jusqu'à ne plus être bloqué.",
	["warte hier auf bürger. verwende slash tar bür und benutze deine fähigkeit todesgriff, um sie zu dir zu ziehen. laufe ihnen nicht nach. sie sind zu schnell."] = "Attendez ici les citoyens. Faites slash tar cit et utilisez votre capacité Poigne de mort pour les attirer à vous. Ne leur courez pas après, ils sont trop rapides.",
	["Der Aufzug ist stumm. Du benötigst die hilfe einer sehenden person."] = "L'ascenseur est muet. Vous avez besoin de l'aide d'une personne voyante.",
	["hier beginnt ein extrem schmaler steg"] = "Ici commence une passerelle extrêmement étroite",
	["dieser aufzug ist stumm. du benötigst sehende hilfe."] = "Cet ascenseur est muet. Vous avez besoin de l'aide d'une personne voyante.",
	["Du musst von hier aus extrem vorsichtig navigieren. Es gibt viele kleine Treppen und Dinge, von denen du herunterfallen könntest."] = "À partir d'ici, vous devez naviguer avec une extrême prudence. Il y a de nombreux petits escaliers et obstacles dont vous pourriez tomber.",
	["warte hier auf die ankunft des zeppelins. der zeppelinmeister wird im chat schreien, wenn er angekommen ist. vorsicht: es gibt verschiedene zeppeline. schau nach, ob dein zeppelin angekommen ist!"] = "Attendez ici l'arrivée du zeppelin. Le maître du zeppelin criera dans le canal de discussion quand il sera arrivé. Attention : il y a plusieurs zeppelins. Vérifiez que c'est bien le vôtre qui est arrivé !",
	["Vorsicht! Ab hier geht es auf diesem Weg im Uhrzeigersinn um eine Schlucht herum. Du läufst am Rand. Präzise laufen!"] = "Attention ! À partir d'ici, ce chemin contourne un ravin dans le sens des aiguilles d'une montre. Vous marchez sur le bord. Avancez avec précision !",
	["Hier kommt der Teleportpunkt aus der Höhle zu Haleh. Einfach ab hier ein paar Schritte vorlaufen."] = "Ici arrive le point de téléportation qui sort de la caverne vers Haleh. Avancez simplement de quelques pas à partir d'ici.",
	["Achtung Trollwelpe"] = "Attention, jeune troll Crins-de-givre",
	["Hier Questgegenstand benutzen"] = "Utilisez ici l'objet de quête",
	["Nächster Punkt ist der Fahrstuhleingang. Der Fahrstuhl hat vier Haltestellen: unten, mitte unten, mitte oben, oben. Er macht beim Ankommen ein lautes Knallgeräusch. Beim Abfahren ein Heulgeräusch. Im Fahrstuhl gibt es ein dauerhaftes Maschinengeräusch. Die Maschine befindet sich zwischen Mitte unten und Mitte oben. Lautstärke an den Haltestellen: unten leises Geräusch, mitte unten und mitte oben laut, oben kein Geräusch."] = "Le prochain point de passage est l'entrée de l'ascenseur. L'ascenseur a quatre arrêts : bas, milieu inférieur, milieu supérieur, haut. Il fait un grand bruit de claquement à l'arrivée. Au départ, il fait un bruit de hurlement. Il y a un bruit de machine constant dans l'ascenseur. La machine se trouve entre le milieu inférieur et le milieu supérieur. Volume aux arrêts : bas bruit faible, milieu inférieur et milieu supérieur fort, haut aucun bruit.",
	["Achtung: Der NPC Hund bewegt sich hier sehr schnell!"] = "Attention : le chien PNJ se déplace très vite ici !",
	["rettungspunkt unten schlucht"] = "Point de sauvetage, au fond du ravin",
	["Hier ist auch das Stammesfeuer!"] = "Le feu tribal est ici aussi !",
	["Achtung, der Weg zur Hauptroute führt an mehreren Bäumlingen Level 52 bis 53"] = "Attention, le chemin vers l'itinéraire principal passe devant plusieurs Tréants de niveau 52 à 53",
	["Kreuzung der Hauptstrasse und dem Weg zur Burg Stromgarde. ... Vorsicht vor dem Kurier der Verlassenen und seiner Leibwache"] = "Croisement de la route principale et du chemin vers Stromgarde. Méfiez-vous de la Messagère des Réprouvés et de son garde du corps",
	["Achtung: Dieser Questnpc bewegt sich!"] = "Attention : ce PNJ de quête se déplace !",
	["Hier tauchen !"] = "Plongez ici !",
	["Beim nächsten Punkt warten !"] = "Attendez au prochain point !",
	["Hier warten bis die Fahr zu Ende ist !!"] = "Attendez ici jusqu'à la fin du trajet !",
	["Hier beim Laufen springen um raus zu kommen!"] = "Sautez ici tout en courant pour sortir !",
	["Hier das Questitem einsetzen !"] = "Placez ici l'objet de quête !",
	["Ein- und Ausgang Schlucht"] = "Entrée et sortie du ravin",
	["Achtung: Nach Osten kommt die nächsten 2 Wegpunkte eine extrem schmale Brücke mit Abgrund."] = "Attention : vers l'est, les 2 prochains points de passage empruntent un pont extrêmement étroit surplombant le vide.",
	["Um den Schlüssel zu diesem Tor zu bekommen, musst du Margol töten und das Horn holen."] = "Pour obtenir la clé de cette grille, vous devez tuer Margol l'Enragée et récupérer la corne.",
	["Vorsicht! Nach Süden geht es über eine schmale Brücke. Nach Osten geh es am Rand einer Schlucht entlang. Nach Norden ist eine sichere Straße."] = "Attention ! Vers le sud, on franchit un pont étroit. Vers l'est, on longe le bord d'un ravin. Vers le nord, la route est sûre.",
	["Vorsicht. Extrem schmale Brücke mit Schlucht."] = "Prudence. Pont extrêmement étroit au-dessus d'un ravin.",
	["Hängebrücke Ende / Questzone"] = "Fin du pont suspendu / zone de quête",
	["Hier springen um rauf zu kommen !"] = "Sautez ici pour monter !",
	["Hier Pulver auf den Stein anwenden, dann Mondklaue töten und mit dem Geist von Mondklaue sprechen. (/tar Geist)  "] = "Appliquez ici la poudre sur la pierre, puis tuez Lunegriffe et parlez à l'Esprit de Lunegriffe. (/tar esprit)",
	["Vorsicht: Navigiere von hier aus vorsichtig, sonst fällst du runter und bleibst stecken"] = "Attention : naviguez prudemment à partir d'ici, sinon vous tombez et vous restez bloqué",
	["rettungspunkt unten schlucht 1"] = "Point de sauvetage, au fond du ravin 1",
	["Achtung, der Mob bewegt sich!"] = "Attention, la créature se déplace !",
	["Stopp. Wenn du unter level 20 bist, und von menethil nach loch modan willst, bleib hier steht. Prüfe, ob vor dir ein mob ist. Wenn das der fall ist, warte hier bis dieser sich wegbewegt hat. laufe erst dann weiter! Solltest du trotzdem angegriffen werden, bleib nicht stehen. lauf weiter der route nach."] = "Stop. Si vous êtes en dessous du niveau 20 et voulez aller de Menethil au Loch Modan, arrêtez-vous ici. Vérifiez s'il y a une créature devant vous. Si c'est le cas, attendez ici qu'elle se soit éloignée et ne puisse plus être ciblée. Puis continuez ! Si vous êtes quand même attaqué, ne vous arrêtez pas : continuez à suivre l'itinéraire pour aller le plus loin possible avant de mourir.",
	["Achtung. Hier kommt ein Fahrstuhl ohne Geräusche nach oben. Um nach oben zu kommen, halte dich genau an die folgenden Schritte: Geh zum nächsten Wegpunkt. Nimm Akolyth der Aldor ins Ziel. Springe so lange immer wieder, bis sich die Entferung zum Ziel verändert. Laufe dann sofort vorwärts, bis du nicht mehr feststeckst. Dann bist oben und kannst zum nächsten Wegpunkt laufen."] = "Attention. Il y a ici un ascenseur silencieux qui monte. Pour monter, suivez exactement les étapes suivantes : descendez de monture ! Allez au point de passage suivant. Ciblez un Acolyte de l'Aldor. Sautez sans arrêt jusqu'à ce que la distance à la cible change. Courez alors immédiatement vers l'avant jusqu'à ne plus être bloqué. Vous êtes alors en haut et pouvez aller au point de passage suivant.",
	["Brückenkopf Jägerlagerbrücke"] = "Tête de pont, pont du camp de chasseurs",
	["Achtung: NPC bewegt sicht!"] = "Attention : le PNJ se déplace !",
	["Kreuzung vom Hauptweg, und dem Weg zur Zuflucht ... Vorsicht vor dem Kurier der Verlassenen und seiner Leibwache"] = "Croisement du chemin principal et du chemin vers le refuge. Méfiez-vous de la Messagère des Réprouvés et de son garde du corps",
	["Achtung hier links ist gleich ein Horde Posten mit Wachen."] = "Attention, juste à gauche se trouve un poste de la Horde avec des gardes.",
	["Achtung: Nach Westen kommt die nächsten 2 Wegpunkte eine extrem schmale Brücke mit Abgrund."] = "Attention : vers l'ouest, les 2 prochains points de passage empruntent un pont extrêmement étroit surplombant le vide.",
	["Du bist im Fahrstuhl. Warte bis die Fahrt zu Ende ist!"] = "Vous êtes dans l'ascenseur. Attendez la fin du trajet !",
	["Achtung: Hier geht eine Rampe hoch. Daher vorsichtig laufen bis zum oberen Punkt."] = "Attention : une rampe monte ici. Avancez donc prudemment jusqu'au point supérieur.",
	["Unterer höhleneingang"] = "Entrée inférieure de la caverne",
	["Achtung: hier geht eine Rampe runter. Daher vorsichtig laufen bis zum unteren Punkt."] = "Attention : une rampe descend ici. Avancez donc prudemment jusqu'au point inférieur.",
	["Achtung: ab hier vorsichtig laufen!"] = "Attention : à partir d'ici, avancez prudemment !",
	["Kreuzung Hauptweg, und der Weg nach Tarrens Mühle und Arathi Hochgebirge ... Achtung! Auf dem Weg von Tarrens Mühle zum Araatchi Hochland läuft der Kurier der Verlassenen mit seiner Leibwache herum. Sehr gefährlich, wenn man nicht bereit ist."] = "Croisement du chemin principal et du chemin vers le Moulin de Tarren et les Hautes-terres d'Arathi ... Attention ! Sur le chemin entre le Moulin de Tarren et les Hautes-terres d'Arathi patrouille la Messagère des Réprouvés avec son garde du corps. Très dangereux si vous n'êtes pas prêt.",
	["Achtung: Läufer der Winterquell auf dem Weg!"] = "Attention : un rôdeur de Berceau-de-l'Hiver sur le chemin !",
	["Die Rampe zum Glutnebelgipfel vorsichtig rauf laufen!"] = "Montez prudemment la rampe jusqu'au pic de Braise !",
	["Falls ihr ins Wasser fällt, dann nach Gewässer, Unten oder Rettungs Punkt suchen!"] = "Si vous tombez à l'eau, cherchez « water » ou « rescue point » pour en sortir !",
	["Achtung: Abhang ist rechts. Den Weg zum Questgeber vorsichtig laufen. "] = "Attention : il y a une pente à droite. Avancez prudemment jusqu'au donneur de quête.",
	["Achtung: Händler läuft hier im Kreis um den See herum!"] = "Attention : le marchand tourne ici en rond autour du lac !",
	["Achtung: Steg start/ende oben"] = "Attention : début / fin de la passerelle, en haut",
	["Vorsicht: Ab hier geht es eine extrem schmale und verwinkelte Rampe ohne Geländer hoch."] = "Attention : à partir d'ici, on monte une rampe extrêmement étroite et sinueuse, sans garde-corps.",
	["Achtung. Hier kommt ein Fahrstuhl ohne Geräusche nach oben. Um nach oben zu kommen, halte dich genau an die folgenden Schritte: Nicht reiten! Geh zum nächsten Wegpunkt. Nimm Anhängerin der Seher ins Ziel. Springe so lange immer wieder, bis sich die Entferung zum Ziel verändert. Laufe dann sofort vorwärts, bis du nicht mehr feststeckst. Dann bist oben und kannst zum nächsten Wegpunkt laufen."] = "Attention. Il y a ici un ascenseur silencieux qui monte. Pour monter, suivez exactement les étapes suivantes : ne montez pas à cheval ! Allez au point de passage suivant. Ciblez un Serviteur des Clairvoyants. Sautez sans arrêt jusqu'à ce que la distance à la cible change. Courez alors immédiatement vers l'avant jusqu'à ne plus être bloqué. Vous êtes alors en haut et pouvez aller au point de passage suivant.",
	["Um rauszugehen laufe auf Sicht zum \\\"Rettung, Punkt,  Höhle, Die blühende Oase, Brachland\\\""] = "Pour sortir, allez à vue jusqu'au point de passage « sauvetage, point, cave, Lushwater Oasis, Les Tarides »",
	["Benutze die Translokationskugel beim nächsten Wegpunkt um nach oben zu kommen."] = "Utilisez la sphère de translocation au prochain point de passage pour monter.",
	["Achtung der Questgeber bewegt sich. Allenfalls beim andern Wegpunkt suchen!"] = "Attention : le donneur de quête se déplace. Trouvez-le à l'autre point de passage s'il n'est pas ici !",
	["Fahrstuhl Freiwindposten!"] = "Ascenseur de Librevent !",
	["Bitte die Translokationskugel benutzen um das Stockwerk zu wechseln"] = "Utilisez la sphère de translocation pour changer d'étage",
	["Ab hier musst du extrem vorsichtig sein. Brücke, Schlucht und Tod lauern."] = "À partir d'ici, vous devez être extrêmement prudent. Pont, ravin et mort vous guettent.",
	["Achtung. Hier kommt ein Fahrstuhl ohne Geräusche nach unten. Du kannst nicht den Fahrstuhl nach unten nehmen. Suche nach dem Wegpunkt Shattrath seher oben nach unten und folge von dort einer Route nach unten."] = "Attention. Il y a ici un ascenseur silencieux qui descend. Vous ne pouvez pas le prendre pour descendre. Cherchez le point de passage « Shattrath scryer up to down » et suivez de là un itinéraire vers le bas.",
	["Ab diesem Punkt kann man den Weg nicht mehr zurücklaufen!"] = "À partir de ce point, vous ne pourrez plus revenir par où vous êtes venu !",
	["Sanath ansprechen um nach oben teleportiert zu werden. Oben nach Nyrill suchen!"] = "Parlez à Sanath pour être téléporté. Puis cherchez Nyrill !",
	["Um den Schlüssel für dieses Tor zu bekommen, musst du Margol töten und das Horn holen."] = "Pour obtenir la clé de cette grille, vous devez tuer Margol l'Enragée et récupérer la corne.",
	["NPC bewegt sich!"] = "Le PNJ se déplace !",
	["Achtung: Du musst am nächsten Wegpunkt anhalten, um auf das Schiff zu warten."] = "Attention : vous devez vous arrêter au prochain point de passage pour attendre le bateau.",
	["Nimm jetzt Akolyth der Aldor ins Ziel und geht zum nächsten Wegpunkt."] = "Ciblez maintenant un Acolyte de l'Aldor et allez au point de passage suivant.",
	["Achtung: Steg start/ende unten"] = "Attention : début / fin de la passerelle, en bas",
	["Achtung der NPC bewegt sich hier im Kreis!"] = "Attention, le PNJ tourne ici en rond !",
	["Achtung: Dieser Mob läuft über den ganzen Strand von Norden nach Süden"] = "Attention : cette créature parcourt toute la plage du nord au sud",
	["Sucht Gammerita zwischen dem südlichem und dem nördlichem Punkt!"] = "Cherchez Gammerita entre le point sud et le point nord !",
	["Questmob bewegt sich (etwas)!"] = "La créature de quête se déplace (un peu) !",
	["Der Aufzug wird von der Horde bewacht, gwählt ist der LINKE Aufzug. Beim Anleger warten bist der Aufzug da ist."] = "L'ascenseur est gardé par la Horde ; celui qui est choisi est l'ascenseur de GAUCHE. Attendez à l'embarcadère que l'ascenseur soit là.",
	["Für die Rückkehr nach unten, mache eine neue Route auf, mit dem Ziel das Portal Oben."] = "Pour redescendre, lancez une nouvelle route avec pour destination le portail du haut.",
	["Achtung: Mob bewegt sich !"] = "Attention : la créature se déplace !",
	["Hier warten!"] = "Attendez ici !",
	["Kreuzung vom Hauptweg, und dem Weg nach Süderstade"] = "Croisement du chemin principal et du chemin vers Austrivage",
	["Achtung der Geistgeber bewegt sich. Allenfalls beim Anderen Wegpunkt suchen!"] = "Attention, le donneur d'esprit se déplace. Le cas échéant, cherchez-le à l'autre point de passage !",
	["Von hier zurück an Land musst du extrem präsizes navigieren."] = "Pour revenir sur la terre ferme à partir d'ici, vous devez naviguer avec une extrême précision.",
	["Achtung, links ist ein Abgrund. Rechts halten und genau laufen!"] = "Attention : il y a un précipice à gauche. Restez à droite et avancez prudemment !",
	["Brückenkopf Jägerlagerbrücke, Kreuzung zum Jägerlager"] = "Tête de pont, pont du camp de chasseurs, croisement vers le camp de chasseurs",
	["Von hier bis zu den Stegen musst du absolut präzise navigieren, sonst fällst du runter oder bleibst stecken."] = "D'ici jusqu'aux passerelles, vous devez naviguer avec une précision absolue, sinon vous tombez ou vous restez bloqué.",
	["Im Fahrstuhl"] = "Dans l'ascenseur",
	["Hier auf das Schiff warten, und wenn es angekommen ist, dann zum nächsten Punkt gehen (Schiff)"] = "Attendez ici le bateau, puis, une fois qu'il est arrivé, aller au point suivant (bateau)",
	["Achtung: Vorsicht, gleich kommt eine hohe Brücke!"] = "Attention : prudence, un pont élevé arrive tout de suite !",
	["Fahrstuhleingang unten. Bei Route in den Fahrstuhl: Warte, bis das Knallgeräusch vom ankommenden Fahrstuhl direkt vor dir zu hören ist (maximal laut). Geh zum nächsten Punkt, der im Fahrstuhl ist. Fahr nur eine Etage hoch bis mitte unten. Geh dann geradeaus wieder aus dem Fahrstuhl raus zum Fahrstuhleingang mitte unten."] = "Entrée de l'ascenseur en bas. Si vous suivez un itinéraire vers l'ascenseur : attendez d'entendre le claquement de l'ascenseur qui arrive juste devant vous (volume maximum). Avancez jusqu'au point suivant, qui est dans l'ascenseur. Montez d'un étage jusqu'au milieu inférieur. Puis sortez tout droit de l'ascenseur jusqu'au point de passage entrée de l'ascenseur milieu inférieur.",
	["Achtung Hängebrücke Anfang."] = "Attention, début du pont suspendu.",
	["Hier ist das untere Ende des Weges von der Aldor- und Seherhöhe nach unten. Er funktioniert nur runter. Du kommst hier nicht rauf. Nimm stattdessen eine Route zum Aldor- oder Seher-Fahrstuhl, wenn du rauf willst."] = "Ici se trouve le bas du chemin qui descend depuis l'Éminence de l'Aldor et le Degré des Clairvoyants. Il ne fonctionne que vers le bas : vous ne pouvez pas remonter par ici. Prenez plutôt une route vers l'ascenseur de l'Aldor ou des Clairvoyants si vous voulez monter.",
	["Achtung, der Gastwirt läuft immer von der einen Seite zur anderen!"] = "Attention, l'aubergiste fait sans cesse la navette d'un côté à l'autre !",
	["Achtung: Ab hier zum nächsten Punkt springen!"] = "Attention : à partir d'ici, sautez jusqu'au point suivant !",
	["Achtung: Priesterin bewegt sich zwischen Höhle und Altar"] = "Attention : la prêtresse se déplace entre la caverne et l'autel",
	["Du bist im Käfig gelandet. Willst du wirklich raus ?"] = "Vous avez atterri dans la cage. Voulez-vous vraiment en sortir ?",
	["Hier ist der Höhleneingang"] = "Ici se trouve l'entrée de la caverne",
	["Östlicher Ein- und Ausgang Schlucht"] = "Entrée et sortie est du ravin",
	["Achtung: der Mob bewegt sich über die ganze Karte. -> Am besten sehende Hilfe suchen!"] = "Attention : la créature se déplace sur toute la carte. -> Le mieux est de chercher l'aide d'une personne voyante !",
	["Warte hier bis du die Glocker hörst. Dann ist das Schiff da. Geh dann zum Wegpunkt Schiff richtung düstermarschen"] = "Attendez ici d'entendre la cloche. Le bateau est alors là. Allez ensuite au point de passage du bateau vers le Marécage d'Éprefange",
	["Ab hier reitet der Level 18 Elite \\\"Matis der Grausame\\\""] = "À partir d'ici rôde l'élite de niveau 18 « Matis le Cruel »",
	["Turm von Burg Cenarius,... unten (Erdgeschoss)"] = "Tour du fort de Cenarius,... en bas (rez-de-chaussée)",
	["Von hier müsst ihr wirklich sehr weit nach Süden schwimmen, bis ein Aufgang/Rampe kommt."] = "D'ici vous devez nager très loin vers le sud jusqu'à atteindre un escalier ou une rampe.",
	["Achtung: Hier musst du mindestens den Ruf \\\"Unfreundlich\\\" bei der Holzschlunderfeste haben!"] = "Attention : vous devez avoir ici au moins la réputation « Inamical » avec le Repaire des Grumegueules !",
	["Benutze hier die Translokationskugel, um wieder nach unten zu kommen."] = "Utilisez ici la sphère de translocation pour redescendre.",
	["Kreuzung Hauptweg und Burg Durnholde"] = "Croisement du chemin principal et de Durnholde",
	["Achtung: Dieser Questgeber bewegt sich! (Howin Schmeichelfeder)"] = "Attention : ce donneur de quête se déplace ! (Howin Genteplume)",
	["Gegenstand in Tasche mit rechts anklicken und dann Kristall mit links anklicken!"] = "Clic droit sur l'objet dans votre sac, puis clic gauche sur le cristal !",
	["Achtung. Hier kommt ein Fahrstuhl ohne Geräusche nach unten. Du kannst nicht den Fahrstuhl nach unten nehmen. Suche nach dem Wegpunkt Shattrath Aldor oben nach unten und folge von dort einer Route nach unten."] = "Attention. Il y a ici un ascenseur silencieux qui descend. Vous ne pouvez pas le prendre pour descendre. Cherchez le point de passage « Shattrath Aldor up to down » et suivez de là un itinéraire vers le bas.",
	["Steinbruchtor. Klicken zum Öffnen."] = "Porte de la carrière. Cliquez pour ouvrir.",
	["Nimm jetzt Anhängerin der Seher ins Ziel und geht zum nächsten Wegpunkt."] = "Ciblez maintenant un Serviteur des Clairvoyants et allez au point de passage suivant.",
	["Achtung: Ab hier genau laufen weiter in die Höhle laufen, da gleich ein grosses Loch in der Mitte ist!"] = "Attention : à partir d'ici, continuez dans la caverne en avançant avec précision, car il y a juste après un grand trou au milieu !",
	["Achtung, gleich springen!"] = "Attention, saut imminent !",
	["Achtung dieser Übergang wird von der Horde bewacht. Durchgang bei einem defekten Palisadenstück."] = "Attention, ce passage est gardé par la Horde. Le passage se fait par une section de palissade brisée.",
	["Vorsicht! Nach Norden geht es über eine enge Brücke. Nach Osten geht es gegen den Urhzeigersinn an einer einem Schluchtrand entlang. Nach Westen geht es im Uhrzeigersinn am Schluchtrand entlang."] = "Attention ! Vers le nord, on franchit un pont étroit. Vers l'est, on longe le bord d'un ravin dans le sens inverse des aiguilles d'une montre. Vers l'ouest, on longe le bord du ravin dans le sens des aiguilles d'une montre.",
	["Vorsicht: Extrem schmale Brücke mit Schlucht!"] = "Attention : pont extrêmement étroit au-dessus d'un ravin !",
	["Nach der Flamme weiterlaufen und nach dem fallen unten neuen Routenpunkt aufnehmen!"] = "Continuez après la flamme et, une fois tombé en bas, prenez un nouveau point de route !",
	["Achtung Gefahr von den Todeswachen von Tarrens Mühle, die an diese Kreuzung ran kommen"] = "Attention, danger venant des Nécrogardes du Moulin de Tarren qui s'approchent de ce croisement",
	["Fahrstuhleingang mitte unten. Bei Route in den Fahrstuhl: Ignoriere den Fahrstuhl einfach. Lauf von hier geradeaus weiter, egal ob der Fahrstuhl da ist. Du fällst eine Etage nach unten und erreichst dort den Fahrstuhleingang unten, von dem du normal die Route weiter läufst. "] = "Entrée d'ascenseur, milieu bas. Si votre route entre dans l'ascenseur : ignorez simplement l'ascenseur. Continuez tout droit à partir d'ici, que l'ascenseur soit là ou non. Vous tombez d'un étage et vous atteignez l'entrée d'ascenseur du bas, d'où vous poursuivez normalement la route.",
	["Achtung: Dieser Weg wird meistens von einem Dschungeldonnerer Level 38 verstellt !"] = "Attention : ce chemin est le plus souvent barré par un Foudroyeur de la Jungle de niveau 38 !",
	["Nyrill ansprechen, um wieder nach unten teleportiert zu werden. "] = "Parlez à Nyrill pour être téléporté vers le bas.",
	["Ab diesem Punkt ganz besonders vorsichtig laufen!"] = "À partir de ce point, avancez avec une prudence toute particulière !",
	["achtung: die nächsten wegpunkte zum steg befinden sich auf einem kleinen laufsteg. navigiere genau, sonst fällst du runter"] = "Attention : les prochains points de passage vers la passerelle se trouvent sur un petit ponton. Naviguez avec précision, sinon vous tombez",
	["warte hier auf die ankunft des zeppelins. der zeppelinmeister wird im chat schreien, wenn er angekommen ist. vorsicht: es gibt verschiedene zeppeline. überprüfe, ob dein zeppelin angekommen ist!"] = "Attendez ici l'arrivée du zeppelin. Le maître du zeppelin criera dans le canal de discussion quand il sera arrivé. Attention : il y a plusieurs zeppelins. Vérifiez que c'est bien le vôtre qui est arrivé !",
	["Entweder du navigierst von hier aus vorsichtig, oder du bist tot"] = "Soit vous naviguez prudemment à partir d'ici, soit vous êtes mort",
	["laufe vorwärts und springe, um auf das Schiff zu kommen"] = "Courez vers l'avant et sautez pour monter sur le bateau",
	["achtung: bevor du die nächsten 3 wegpunkte zum pferd gehst, warte und halte nach stallmeister kitrik Ausschau. er läuft in einem sehr großen kreis nördlich von dir, und er ist ein Killer! warte, bis er in maximaler reichweite ist."] = "Attention : avant de parcourir les 3 prochains points de passage vers le cheval, attendez et guettez le Maître des écuries Kitrik. Il tourne en très grand cercle au nord de vous, et c'est un tueur ! Attendez qu'il soit à distance maximale.",
	["beim pferd warte nicht. steige sofort auf das pferd. oder der stallmeister wird dich töten."] = "Au cheval, n'attendez pas. Montez immédiatement sur le cheval, sinon le maître d'écurie te tuera.",
	["Auf dem Pferd, warte nicht. Starte sofort eine Route zurück zum Questgeber und folge dieser Route, ohne anzuhalten oder zu kämpfen."] = "Sur le cheval, n'attendez pas. Lancez immédiatement une route de retour vers le donneur de quête et suis cette route sans vous arrêter ni combattre.",
	["Ich wiederhole: Halte. Nicht. An."] = "Je répète : ne. vous. arrêtez. pas.",
	["verwende die Kanone, um den Kampf zu beginnen. die Kanone hat zwei Knöpfe (1 und 2). Benutze beide abwechselnd so schnell wie möglich. Benutze dabei den Links/Rechts Pfeil und bewege die Kanone 10 kleine Schritte nach links und dann 10 kleine Schritte nach rechts. wiederhole das. Wenn du stirbst, warte auf die Wiederauferstehung, steige wieder in die Kanone und mach weiter. Wiederhole das Ganze, bis die Quest geschafft ist."] = "Utilisez le canon pour déclencher le combat. Le canon a deux boutons (1 et 2). Utilisez-les tous les deux en alternance, aussi vite que possible. En même temps, avec les flèches gauche et droite, déplacez le canon de 10 petits pas vers la gauche puis de 10 petits pas vers la droite. Répétez. Si vous mourez, attendez la résurrection, remontez dans le canon et continuez. Répétez jusqu'à ce que la quête soit accomplie.",
	["Benutze den Gegenstand hier"] = "Utilisez l'objet ici",
	["Wenn du mit Hochlord Mograine gesprochen hast, beginnt die Schlacht nach einer gewissen Zeit automatisch (bis zu 5 Minuten). Warte einfach bei Mograine. Wenn die Schlacht beginnt, wird Hochlord Mograine schreien. Nimm dann eine Route zum Wegpunkt \\\"Die Schlacht\\\", um ihm zu folgen."] = "Une fois que vous avez parlé au Généralissime Darion Mograine, la bataille commence automatiquement au bout d'un certain temps (jusqu'à 5 minutes). Attendez simplement près de Mograine. Quand la bataille commence, le Généralissime Darion Mograine crie. Prenez alors une route vers le point de passage « The Battle » pour le suivre.",
	["Warte hier, bis die Schlacht vorbei ist. Du wirst einen sehr langen Dialog hören. Wenn der Dialog vorbei ist, ist die Quest abgeschlossen. Gehe zum Wegpunkt \\\"Ende Schlacht\\\" und sprich mit Hochlord Darion Mograine."] = "Attendez ici la fin de la bataille. Vous entendrez un très long dialogue. Quand le dialogue est terminé, la quête est accomplie. Allez au point de passage « Battle end » et parlez au Généralissime Darion Mograine.",
	["warte hier bis du den fahrstuhl ankommen hörst. geh dann zum punkt auf dem fahrstuhl unten kriegshymnenfeste"] = "Attendez ici d'entendre l'ascenseur arriver. Allez ensuite au point « on the elevator bottom Warsong Hold »",
	["geh zum punkt auf dem fahrstuhl oben kriegshymnenfeste. warte bis der fahrstuhl oben ist. geh dann zum punkt fahrstuhl oben kriegshymnenfeste"] = "Allez au point « on the elevator top warsong hold ». Attendez que l'ascenseur soit en haut. Allez ensuite au point « elevator top Warsong Hold »",
	["geh zum punkt auf dem fahrstuhl unten kriegshymnenfeste. warte bis der fahrstuhl unten ist. geh dann zum punkt fahrstuhl unten kriegshymnenfeste"] = "Allez au point « on the elevator bottom Warsong Hold ». Attendez que l'ascenseur soit en bas. Allez ensuite au point « elevator bottom warsong hold »",
	["warte bis du den fahrstuhl kommen hörst. geh dann zum punkt auf dem fahrstuhl oben kriegshymnenfeste."] = "Attendez d'entendre l'ascenseur arriver. Allez ensuite au point « on the elevator top warsong hold ».",
	["Das Gefängnis schwebt in der Luft. Ab hier musst du fliegen, um es zu erreichen."] = "La prison flotte dans les airs. À partir d'ici, vous devez voler pour l'atteindre.",
	["Das Gefägnis schwebt in der Luft."] = "La prison flotte dans les airs.",
	["behüter rupert kühnauge steht oben auf einem turm."] = "Le gardien Rupert Kühnauge se tient en haut d'une tour.",
	["Du kannst die Plattform von hier aus nicht zerstören. Gehe zu den Wegpunkten mit dem Namen \\\"Ostplattform Zerstörungspunkt Boreanische Tundra\\\""] = "Vous ne pouvez pas détruire la plate-forme d'ici. Allez aux points de passage nommés « East Platform Destroy point Borean Tundra »",
	["Du muss hier auf das Schiff warten. Es macht keine Geräusche. Verwendet immer wieder /tar qat (q a t), um einen npc auf dem Schiff ins zu nehmen. Sobald das funktioniert ist das schiff da. Warte dann noch 10 sekunden und geh zum Wegpunkt \\\"auf dem schiff nach drachenöde\\\"."] = "Vous devez attendre le bateau ici. Il ne fait aucun bruit. Utilisez sans arrêt /tar qat (q a t) pour cibler un PNJ sur le bateau. Dès que ça fonctionne, le bateau est là. Attendez alors encore 10 secondes et allez au point de passage « on the ship to dragonblight ».",
	["Du muss hier auf das Schiff warten. Es macht keine Geräusche. Verwendet immer wieder /tar qat (q a t), um einen npc auf dem Schiff ins zu nehmen. Sobald das funktioniert ist das schiff da. Warte dann noch 20 sekunden und geh zum Wegpunkt \\\"auf dem schiff nach heulender fjord\\\"."] = "Vous devez attendre le bateau ici. Il ne fait aucun bruit. Utilisez sans arrêt /tar qat (q a t) pour cibler un PNJ sur le bateau. Dès que ça fonctionne, le bateau est là. Attendez alors encore 20 secondes et allez au point de passage « on the ship to howling fjord ».",
	["Die fahrt nach heulender fjord dauert mehr als 3 minuten. Verwendet immer wieder /tar Nut (n u t), um festzustellen, ob du schon angekommen bist. Sobald du Nutaaq ins ziel nehmen kannst, bist du in heulender fjord. Warte dann noch 20 sekunden, und verlasse das schiff zum Wegpunkt \\\"anleger heulender fjord nach drachenöde\\\"."] = "La traversée vers le Fjord Hurlant dure plus de 3 minutes. Utilisez sans arrêt /tar Nut (n u t) pour savoir si vous êtes déjà arrivé. Dès que vous pouvez cibler Nutaaq, vous êtes dans le Fjord Hurlant. Attendez alors encore 20 secondes, puis quittez le bateau vers le point de passage « pier howling fjord to dragonblight ».",
	["Die fahrt nach boreanische tundra dauert mehr als 3 minuten. Verwendet immer wieder /tar agl (a g l), um festzustellen, ob du schon angekommen bist. Sobald du agloolik ins ziel nehmen kannst, bist du in boreanische tundr. Warte dann noch 20 sekunden, und verlasse das schiff zum Wegpunkt \\\"anleger boreanische tundra nach drachenöde\\\"."] = "La traversée vers la Toundra Boréenne dure plus de 3 minutes. Utilisez sans arrêt /tar agl (a g l) pour savoir si vous êtes déjà arrivé. Dès que vous pouvez cibler Agloolik, vous êtes dans la Toundra Boréenne. Attendez alors encore 20 secondes, puis quittez le bateau vers le point de passage « pier borean tundra to dragonblight ».",
	["Du muss hier auf das Schiff warten. Es macht keine Geräusche. Verwendet immer wieder /tar nag (n a g), um einen npc auf dem Schiff ins zu nehmen. Sobald das funktioniert ist das schiff da. Warte dann noch 20 sekunden und geh zum Wegpunkt \\\"auf dem schiff nach drachenöde\\\"."] = "Vous devez attendre le bateau ici. Il ne fait aucun bruit. Utilisez sans arrêt /tar nag (n a g) pour cibler un PNJ sur le bateau. Dès que ça fonctionne, le bateau est là. Attendez alors encore 20 secondes et allez au point de passage « on the ship to dragonblight ».",
	["Die fahrt nach drachenöde dauert mehr als 3 minuten. Verwendet immer wieder /tar kan (k a n), um festzustellen, ob du schon angekommen bist. Sobald du Kanosak ins ziel nehmen kannst, bist du in drachenöde. Warte dann noch 20 sekunden, und verlasse das schiff zum Wegpunkt \\\"anleger drachenöde nach heulender fjord\\\"."] = "La traversée vers la Désolation des dragons dure plus de 3 minutes. Utilisez sans arrêt /tar kan (k a n) pour savoir si vous êtes déjà arrivé. Dès que vous pouvez cibler Kanosak, vous êtes dans la Désolation des dragons. Attendez alors encore 20 secondes, puis quittez le bateau vers le point de passage « pier dragonblight to howling fjord ».",
	["Du muss hier auf das Schiff warten. Es macht keine Geräusche. Verwendet immer wieder /tar nag (n a g), um einen npc auf dem Schiff ins zu nehmen. Sobald das funktioniert ist das schiff da. Warte dann noch 20 sekunden und geh zum Wegpunkt \\\"auf dem schiff nach boreanische tundra\\\"."] = "Vous devez attendre le bateau ici. Il ne fait aucun bruit. Utilisez sans arrêt /tar nag (n a g) pour cibler un PNJ sur le bateau. Dès que ça fonctionne, le bateau est là. Attendez alors encore 20 secondes et allez au point de passage « on the ship to borean tundra ».",
	["du bist auf einer insel. um auf das festland zu kommen, benötigst du die hilfe einer sehenden person. die seilbahn ist leider stumm."] = "Vous êtes sur une île. Pour rejoindre la terre ferme, vous avez besoin de l'aide d'une personne voyante : le téléphérique est malheureusement muet.",
	["um auf die insel zu kommen, benötigst du die hilfe einer sehenden person. die seilbahn ist leider stumm."] = "Pour rejoindre l'île, vous avez besoin de l'aide d'une personne voyante : le téléphérique est malheureusement muet.",
	["hier warten bis du das horn hörst. dann ist der zeppelin da. dann zum wegpunkt \\\"Heulender Fjord auf zeppelin\\\" gehen."] = "Attendez ici d'entendre le cor. Le zeppelin est alors là. Allez ensuite au point de passage « howling fjord on zeppelin ».",
	["warte auf die glocke. Dann geh zum Wegpunkt \\\"auf dem schiff boreanische tundra nach sturmwind\\\""] = "Attendez la cloche. Allez ensuite au point de passage « on the ship borean tundra to stormwind »",
	["du musst hier mit einem stummen fahrstuhl fahren. von unten nach oben geh von hier springend auf den punkt \\\"auf fahrstuhl\\\" zu bis du kurz nicht mehr den feststecken ton hörst. zähl dann 10 sekunden ab und geh sofort zum Punkt \\\"fahrstuhl oben\\\"."] = "Vous devez ici emprunter un ascenseur muet. Du bas vers le haut, avancez d'ici en sautant vers le point « on elevator » jusqu'à ce que le son de blocage cesse un court instant. Comptez alors 10 secondes et allez immédiatement au point « elevator up ».",
	["du musst hier mit einem stummen fahrstuhl fahren. von oben nach unten geh einfach zum punkt \\\"auf fahrstuhl\\\". du fällst nicht tief. geh dann zu \\\"fahrstuhl unten\\\"."] = "Vous devez ici emprunter un ascenseur muet. Du haut vers le bas, allez simplement au point « on elevator ». Vous ne tombez pas de haut. Allez ensuite à « elevator bottom ».",
	["nach dem benutzen des räuchergefäßes zum wegpunkt \\\"installation der drachenschinder\\\" gehen."] = "Après avoir utilisé le brasero à encens, allez au point de passage « Ancient Male Vrykul ».",
	["Vor dir liegt ein Minenfeld. Wenn du der Route nicht genau folgst, wirst du sehr überrascht sein."] = "Un champ de mines se trouve devant vous. Si vous ne suivez pas exactement la route, vous aurez une très mauvaise surprise.",
	["grom'arsh Absturzstelle Landepunkt; Sturmgipfel"] = "Point d'atterrissage du site du crash de Grom'arsh ; Pics Foudroyés",
	["bleib hier stehen und mach so lange /tar kapitän bis du kapitän ellis im ziel hast. Warte dann weiter bis die Entfernung 28 meter angesagt wird. dann ist das schiff da. folge dann der route weiter zu kapitän ellis. beeil dich, das schiff fährt nach 2 minuten wieder los."] = "Restez ici et faites /tar capitaine jusqu'à avoir le Capitaine Ellis en cible. Attendez ensuite que la distance de 28 mètres soit annoncée : le bateau est alors là. Suivez alors la route jusqu'au Capitaine Ellis. Dépêchez-vous, le bateau repart au bout de 2 minutes.",
	["stop. geh nicht weiter. vor dir ist eine schlucht. klauenwürger fliegt vor dir über der schlucht im kreis. bleib hier stehen, nimm ihn ins ziel, und versuch auf ihn zu schießen. geht nicht weiter der route nach!"] = "Stop. N'allez pas plus loin. Un ravin se trouve devant vous. Serre-grièche vole en cercle au-dessus du ravin devant vous. Restez ici, ciblez-le et essayez de lui tirer dessus. Ne continuez pas la route !",
	["geh ein paar schritte vorwärts um den teleporter zu nehmen"] = "Avancez de quelques pas pour prendre le téléporteur",
	["hier auf das schiff warten. die glocke läutet wenn das schiff da ist."] = "Attendez ici le bateau. La cloche sonne quand le bateau est là.",
	["Lande hier und folge der Rute am Boden zu Athan."] = "Atterrissez ici et suivez la route au sol jusqu'à Athan.",
	["Fliege hier auf dem Wegpunkt 3 sekunden gerade nach unten, um zu laden. Fliege dann für eine halbe Sekunde gerade nach oben. Dreh dich dann exakt zum nächsten Wegpunkt und fliege zu diesem. Du musst ihn genau treffen."] = "Ici, sur le point de passage, volez 3 secondes droit vers le bas pour vous poser. Volez ensuite droit vers le haut pendant une demi-seconde. Tournez-vous alors exactement vers le point de passage suivant et volez jusqu'à lui. Vous devez l'atteindre précisément.",
	["Ab hier geht es in eine Höhle, die du durchfliegen musst. Das ist extrem schwierig, und du solltest es mit sehender Hilfe machen. Wenn du es trotzdem probieren möchtest, folge ab hier den Anweisungen, um in die Höhle zu Athan zu kommen. Heraus kommst du nur per Ruhestein oder Teleport. Lande hier exakt auf diesem Wegpunkt. Dreh dich am Boden zum nächsten Wegpunkt. Fliege dann für exakt 2 Sekunden nach oben. Fliege dann zum nächsten Wegpunkt, den du exakt treffen musst."] = "À partir d'ici, vous entrez dans une caverne que vous devez traverser en vol. C'est extrêmement difficile et vous devriez le faire avec l'aide d'une personne voyante. Si vous voulez quand même essayer, suivez les instructions à partir d'ici pour rejoindre Athan dans la caverne. Vous n'en ressortirez que par pierre de foyer ou téléportation. Atterrissez ici exactement sur ce point de passage. Au sol, tournez-vous vers le point de passage suivant. Volez ensuite exactement 2 secondes vers le haut. Volez enfin jusqu'au point de passage suivant, que vous devez atteindre exactement.",
	["Vorsicht: Halte am nächsten Wegpunkt an"] = "Attention : arrêtez-vous au prochain point de passage",
	["warte hier auf das Schiff. du wirst eine Glocke hören. dann fahre zwei Wegpunkte weiter zum Hafen Sturmwind auf dem Schiff zur Dunkelküste."] = "Attendez ici le bateau. Vous entendrez une cloche. Avancez ensuite de deux points de passage jusqu'au port de Hurlevent, sur le bateau vers Sombrivage.",
	["hier beginnt eine extrem schmale treppe. bewege dich sehr, sehr genau."] = "Ici commence un escalier extrêmement étroit. Déplacez-vous très, très précisément.",
	["hier beginnt/endet eine extrem schmale treppe. bewege dich sehr, sehr genau."] = "Ici commence / se termine un escalier extrêmement étroit. Déplacez-vous très, très précisément.",
	["Vorsicht: Du musst am nächsten Wegpunkt anhalten"] = "Attention : vous devez vous arrêter au prochain point de passage",
	["halte hier an und warte auf das Schiff. du wirst eine Glocke hören. dann bewege dich zwei Wegpunkte zu Hafen Sturmwind auf dem Schiff nach Boreanische Tundra"] = "Arrêtez-vous ici et attendez le bateau. Vous entendrez une cloche. Avancez ensuite de deux points de passage jusqu'au port de Hurlevent, sur le bateau vers la Toundra Boréenne",
	["warte hier auf das Schiff zum Heulenden Fjord. es ertönt eine Glocke. bewege dich dann zwei Wegpunkte auf das Schiff zum Heulenden Fjord"] = "Attendez ici le bateau vers le Fjord Hurlant. Une cloche retentit. Avancez ensuite de deux points de passage sur le bateau vers le Fjord Hurlant",
	["warte hier auf die Ankunft des Zeppelins. du wirst ein Horn hören. bewege dich dann zwei Wegpunkte auf den Zeppelin nach Donnerfels"] = "Attendez ici l'arrivée du zeppelin. Vous entendrez un cor. Avancez ensuite de deux points de passage sur le zeppelin vers Les Pitons du Tonnerre",
	["warte hier auf die Ankunft des Zeppelins. du wirst ein Horn hören. dann bewege dich zwei Wegpunkte auf den Zeppelin nach Boreanische Tundra"] = "Attendez ici l'arrivée du zeppelin. Vous entendrez un cor. Avancez ensuite de deux points de passage sur le zeppelin vers la Toundra Boréenne",
	["warte hier auf die ankunft des zeppelins. du wirst ein horn hören. bewege dann zwei wegpunkte zu on zepplin nach orgrimmar"] = "Attendez ici l'arrivée du zeppelin. Vous entendrez un cor. Avancez ensuite de deux points de passage jusqu'à « on zeppelin » vers Orgrimmar",
	["Vorsicht: Du musst von hier bis zum Steg extrem genau navigieren, sonst fällst du runter oder bleibst stecken"] = "Attention : d'ici jusqu'à la passerelle, vous devez naviguer avec une extrême précision, sinon vous tombez ou vous restez bloqué",
	["Erst die geheimnisvollen gespinste zerstören"] = "Détruisez d'abord les mystérieuses toiles",
	["Der nächste Wegpunkt Richtung Kurbelzisch ist ein Fahrstuhl. Du musst genau auf dem Wegpunkt stehen."] = "Le prochain point de passage en direction de Spumelevier est un ascenseur. Vous devez vous tenir exactement sur le point de passage.",
	["Springe hier auf dem Fahrstuhl wegpunkt für 10 Sekunden, um sicher auf der Fahrstuhlplattform zu stehen. Wenn der Fahrstuhl oben oder unten losfährt, macht er das Zisch Geräusch. Wenn er ankommt, macht er das Klack Geräusch. Du kannst leider nicht feststellen, ob der Fahrstuhl oben oder unten ist. Du musst rumprobieren. Um nach oben zu kommen, musst du auf dem Fahrstuhl stehen und dann auf gut glück beim klack geräusch zu kurbelzisch loszulaufen. Wenn das nicht klappt, bist du leider unten losgelaufen. Geh wieder auf den Fahrstuhl, springe 10 Sekunden, und lauf dann beim nächsten Klack los. Mach das so lange, bist du glück hast und Kurbelzisch erreichst."] = "Sautez ici sur le point de passage de l'ascenseur pendant 10 secondes pour vous tenir sûrement sur la plate-forme. Quand l'ascenseur part vers le haut ou vers le bas, il fait un bruit de sifflement. Quand il arrive, il fait un bruit de claquement. Vous ne pouvez malheureusement pas savoir s'il est en haut ou en bas : il faut tâtonner. Pour monter, tenez-vous sur l'ascenseur puis lancez-vous au hasard vers Spumelevier au bruit de claquement. Si ça ne marche pas, c'est que vous êtes parti d'en bas. Remontez sur l'ascenseur, sautez 10 secondes, puis repartez au claquement suivant. Recommencez jusqu'à avoir de la chance et atteindre Spumelevier.",
	["fliege hier 15 sekunden gerade nach unten, wenn du auf dem weg in die icc instanzen bist. geh erst danach weiter zum nächsten wegpunkt."] = "Volez ici 15 secondes droit vers le bas si vous êtes en route vers les instances d'ICC. Ne continuez vers le point de passage suivant qu'après.",
	["fliege hier 15 sekunden gerade nach oben, wenn du auf dem weg in die icc instanzen bist. gehe erst danach weiter zum nächsten wegpunkt."] = "Volez ici 15 secondes droit vers le haut si vous êtes en route vers les instances d'ICC. Ne continuez vers le point de passage suivant qu'après.",
	["warte hier auf das Schiff nach Dunkelküste. es ertönt eine Glocke. bewege dich dann zwei Wegpunkte auf das Schiff nach Dunkelküste"] = "Attendez ici le bateau vers Sombrivage. Une cloche retentit. Avancez ensuite de deux points de passage sur le bateau vers Sombrivage",
	["Gehe zum Wegpunkt \\\"auf fahrstuhl\\\". Springe dann mehrmals auf der stelle, um auf den Aufzug zu gelangen, bis du hörst, dass die Umgebungsgeräusche lauter und leiser werden. Dann steht du auf dem sich bewegenden fahrstul. Warte dann, bis die Geräusche laut sind. Dann ist der Aufzug oben. Gehe in dem Moment schnell zum Wegpunkt \\\"Fahrstuhl oben\\\", um den Fahrstuhl zu verlassen."] = "Allez au point de passage « on elevator ». Sautez ensuite plusieurs fois sur place pour monter sur l'ascenseur, jusqu'à entendre les bruits d'ambiance monter et descendre en volume. Vous êtes alors sur la plate-forme en mouvement. Attendez ensuite que les bruits soient forts : l'ascenseur est en haut. Allez vite à ce moment-là au point de passage « elevator top » pour quitter l'ascenseur.",
	["Hier auf den Aufzug warten !"] = "Attendez ici l'ascenseur !",
	["Hier auf das Schiff warten!"] = "Attendez ici le bateau !",
	["Hier auf Zeppelin warten!"] = "Attendez ici le zeppelin !",
	["Warten auf Schiff"] = "Attendez le bateau",
	["Um das Tor für die Zerschmetternden Hallen aufzumachen, brauchst du einen Schlüssel."] = "Pour ouvrir la porte des Salles brisées, il vous faut une clé.",
	["Von hier 2 sekunden geradeaus laufen, um durch das portal zu gehen."] = "À partir d'ici, avancez tout droit pendant deux secondes pour franchir le portail.",
	["Springe so lange dauerhaft, bis sich die Entferung zum Ziel verändert. Laufe dann sofort vorwärts, bis du nicht mehr feststeckst."] = "Sautez sans vous arrêter jusqu'à ce que la distance jusqu'à la cible change. Courez alors immédiatement vers l'avant jusqu'à ne plus être bloqué.",
	["warte hier auf die bürger. verwendet slash tar bür und benutze deine todesgriff fähigkeit, um sie zu dir zu ziehen. laufe ihnen nicht hinterher. sie sind zu schnell."] = "Attendez ici les citoyens. Faites slash tar cit et utilisez votre capacité Poigne de mort pour les attirer à vous. Ne leur courez pas après, ils sont trop rapides.",
	["fliegen starten / beenden"] = "Début / fin du vol",
	["Suche und töte Margol, wenn du Kotka's Weg folgen willst ... Margol's Horn verschaft dir den Durchgang"] = "Cherchez et tuez Margol l'Enragée si vous voulez suivre le chemin de Kotka ... la corne de Margol vous ouvre le passage",
}
